# Batch 1: Confidence, Courage, Creativity, Discipline, Fitness, Friendship, Gratitude

BATCH1_QUOTES = {
    "Confidence": [
        {"id": "q_4", "text": "You have survived every single difficult afternoon that ever threatened to overwhelm you. Trust the quiet resilience that carried you to this room.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Confident,Calm", "situations": "Need Confidence,Difficult Day"},
        {"id": "q_50", "text": "Do not wait for permission from the world to value your own voice. Sing the note that was given to you, clear and unhurried.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Confident,Hopeful", "situations": "Morning,Starting Over"},
        {"id": "q_conf_1", "text": "Confidence is not the absence of trembling hands; it is stepping forward while the heart still flutters.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Determined", "situations": "Need Confidence,Before Work"},
        {"id": "q_conf_2", "text": "You don't have to convince the room that you belong here. Walk in as though you were invited by life itself.", "author": "Stillwords", "isOriginal": True, "moods": "Confident", "situations": "Before Work,Need Confidence"},
        {"id": "q_conf_3", "text": "True confidence is quiet. It never needs to shout or dominate; it rests gently on knowing what you stand for.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Confident", "situations": "Morning,Before Work"},
        {"id": "q_conf_4", "text": "When comparison knocks at your door, do not invite it to tea. Your path was never meant to mirror someone else's timeline.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Difficult Day,Starting Over"},
        {"id": "q_conf_5", "text": "Give yourself credit for the silent battles you won alone, the ones nobody saw and nobody clapped for.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_conf_6", "text": "You carry within you an intuition that has been listening long before your doubts learned how to speak.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Need Confidence,Morning"},
        {"id": "q_conf_7", "text": "Stand tall, not to appear larger than others, but so you may look clearly upon the horizon of your own possibilities.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Confident", "situations": "Morning,Before Work"},
        {"id": "q_conf_8", "text": "A tree does not consult its neighbors before reaching upward toward the sunlight. Follow your own natural light.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Confident", "situations": "Starting Over,Morning"},
        {"id": "q_conf_9", "text": "Do not shrink yourself so other people feel comfortable around your edges. Take up the space you were born to inhabit.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Determined", "situations": "Need Confidence,Starting Over"},
        {"id": "q_conf_10", "text": "Doubt is only a cloud passing through your weather; it is not the sky itself. You are the sky.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Need Confidence"},
        {"id": "q_conf_11", "text": "Trust the wisdom of your hands when they build, and the wisdom of your tongue when it chooses honesty over ease.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Confident", "situations": "Before Work,Study Time"},
        {"id": "q_conf_12", "text": "Self-assurance is not knowing you will always succeed; it is knowing you will survive and learn if you stumble.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Difficult Day,Starting Over"},
        {"id": "q_conf_13", "text": "Listen to the quiet voice beneath the chatter of fear. It rarely argues; it simply points the way forward.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Morning,Need Focus"},
        {"id": "q_conf_14", "text": "You do not need to arrive fully polished. The rough edges are where light catches and where character shows through.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Peace", "situations": "Starting Over,Difficult Day"},
        {"id": "q_conf_15", "text": "Let your work be your answer to cynicism. Craft something genuine and let its honesty speak for itself.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_conf_16", "text": "There is a profound dignity in doing your small part with wholehearted dedication. Never mistake quietness for weakness.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Before Work,Morning"},
        {"id": "q_conf_17", "text": "Do not let the impatience of onlookers dictate the tempo of your unfolding. A deep oak takes decades to mature.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Confident", "situations": "Difficult Day,Starting Over"},
        {"id": "q_conf_18", "text": "When you walk with purpose, the path clears itself before you one step at a time.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Focused", "situations": "Morning,Before Work"},
        {"id": "q_conf_19", "text": "Your value was never something you had to earn through exhaustion. You were worthy before you produced a single thing today.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_conf_20", "text": "Wear your mistakes as scars of honest striving. They are proof you were brave enough to test reality.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Difficult Day,Starting Over"},
        {"id": "q_conf_21", "text": "Be the steady presence you needed when you were feeling lost. You have grown into that guardian now.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Morning,Difficult Day"},
        {"id": "q_conf_22", "text": "Trust what you know by experience, even when public opinion tells you to doubt your senses.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_conf_23", "text": "A quiet heart is not easily shaken by the winds of casual criticism. Root deeply in what matters.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Confident", "situations": "Difficult Day,Morning"},
        {"id": "q_conf_24", "text": "Give yourself the grace of being a beginner today. Mastery is just patience repeated a thousand times.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Calm", "situations": "Starting Over,Study Time"},
        {"id": "q_conf_25", "text": "No one else sees the world through your exact vantage point. What you notice is a gift meant to be shared.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Hopeful", "situations": "Morning,Need Confidence"},
        {"id": "q_conf_26", "text": "Do not seek approval from people whose values you would not seek advice from. Keep your compass true.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Before Work,Difficult Day"},
        {"id": "q_conf_27", "text": "Every morning is a clean white slate. Whatever went unfinished yesterday cannot define the courage of this dawn.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Motivated", "situations": "Morning,Starting Over"},
        {"id": "q_conf_28", "text": "Trust the slow compounding of your efforts. Even small seeds split open granite boulders in time.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Calm", "situations": "Study Time,Before Work"}
    ],

    "Courage": [
        {"id": "q_11", "text": "Courage is rarely a loud trumpet. Most days, it is the soft voice at evening that whispers, 'I will rest, and I will try again tomorrow.'", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Hopeful,Calm", "situations": "Difficult Day,Starting Over"},
        {"id": "q_13", "text": "He who has a why to live can bear almost any how.", "author": "Friedrich Nietzsche", "isOriginal": False, "source": "Twilight of the Idols", "moods": "Determined,Thoughtful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_cour_1", "text": "Bravery is doing the necessary thing quietly, even when your pulse is racing against your ribs.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Need Confidence,Before Work"},
        {"id": "q_cour_2", "text": "Stand in the gale and breathe. You were built with bone and sinew that have survived thousands of winters.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Difficult Day,Workout"},
        {"id": "q_cour_3", "text": "Courage begins the moment you decide that truth is more important than comfort.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Confident", "situations": "Starting Over,Before Work"},
        {"id": "q_cour_4", "text": "Do not wait for fear to leave before you make your move. Take fear by the elbow and walk forward together.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Need Confidence,Starting Over"},
        {"id": "q_cour_5", "text": "It takes immense bravery to admit you were wrong, and even more to lay down your defenses and begin anew.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Healing", "situations": "Starting Over,Difficult Day"},
        {"id": "q_cour_6", "text": "The dark night does not extinguish the candle flame; it only proves how much darkness one tiny spark can conquer.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_cour_7", "text": "Speak the kind truth when staying silent would be easier. The world is hungry for honest gentle courage.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Thoughtful", "situations": "Before Work,Need Confidence"},
        {"id": "q_cour_8", "text": "A ship is safe in harbor, but its keel was curved for the open salt waves. Push away from the pier.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Confident", "situations": "Morning,Starting Over"},
        {"id": "q_cour_9", "text": "The greatest act of courage is often just letting yourself be seen without a mask or armor.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Morning"},
        {"id": "q_cour_10", "text": "Stand your ground with kindness. You do not need harshness to be unbreakable.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Before Work,Difficult Day"},
        {"id": "q_cour_11", "text": "When the road turns steep, shorten your stride and keep your eyes on the next three paces.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Workout,Difficult Day"},
        {"id": "q_cour_12", "text": "Hold onto your convictions even when the room falls quiet. Integrity never required a chorus.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Thoughtful", "situations": "Before Work,Need Focus"},
        {"id": "q_cour_13", "text": "You do not have to conquer the whole mountain before sunset. You only have to pitch your tent a little higher than yesterday.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Hopeful", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_cour_14", "text": "To ask for help when you are drowning is not weakness; it is the ultimate refusal to give up.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Starting Over"},
        {"id": "q_cour_15", "text": "Courage is saying no to what drains your soul so you can say an honest yes to what gives you life.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Calm", "situations": "Morning,Before Work"},
        {"id": "q_cour_16", "text": "Do not let the fear of being misunderstood keep you from living an authentic life.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Starting Over,Need Confidence"},
        {"id": "q_cour_17", "text": "Every brave deed in history began with a single person who refused to accept that despair was the only option.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Hopeful", "situations": "Morning,Before Work"},
        {"id": "q_cour_18", "text": "Meet uncertainty with an open palm rather than a clenched fist. What you cannot control cannot hold you hostage.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_cour_19", "text": "The bird does not doubt the branch; it trusts the feathers on its own wings.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Hopeful", "situations": "Morning,Starting Over"},
        {"id": "q_cour_20", "text": "When you face the storm head on, you cut the time spent in the rain by half.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Workout,Difficult Day"},
        {"id": "q_cour_21", "text": "Dare to look at what hurts without looking away. Healing always begins with honest sight.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Thoughtful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_cour_22", "text": "A spine of steel is forged in ordinary hours when you choose patience over exasperation.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Difficult Day"},
        {"id": "q_cour_23", "text": "Do not surrender your dreams to the cynical laughter of those who gave up on theirs.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Need Confidence,Starting Over"},
        {"id": "q_cour_24", "text": "The wilderness is where character learns its true name. Welcome the unfamiliar trail.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Thoughtful", "situations": "Starting Over,Morning"},
        {"id": "q_cour_25", "text": "There is valor in gentle endurance. The granite riverbed withstands the torrent simply by remaining.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_cour_26", "text": "When you have nothing left to prove, every step becomes an act of genuine freedom.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Confident", "situations": "Starting Over,Morning"},
        {"id": "q_cour_27", "text": "Hold your head steady when the noise rises. A deep ocean remains unmoved by surface foam.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Before Work,Difficult Day"},
        {"id": "q_cour_28", "text": "Take the leap when duty calls. Gravity will catch the feet of the person who moves with honest conviction.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Motivated", "situations": "Need Confidence,Morning"}
    ],

    "Creativity": [
        {"id": "q_crea_1", "text": "Creativity is paying such fierce attention to the ordinary that it begins to sing back to you.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Happy", "situations": "Morning,Study Time"},
        {"id": "q_crea_2", "text": "Leave white space around your days. An overcrowded calendar is the graveyard of imagination.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Before Work"},
        {"id": "q_crea_3", "text": "The blank page is not an interrogation; it is an open clearing waiting for you to plant your thoughts.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Motivated", "situations": "Study Time,Starting Over"},
        {"id": "q_crea_4", "text": "Make something clumsy today. Perfectionism is just fear wrapped in expensive silk.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Confident", "situations": "Study Time,Need Confidence"},
        {"id": "q_crea_5", "text": "The hands often know how to solve a riddle that the intellect has struggled with in vain. Start making.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_crea_6", "text": "Carry a notebook as if your thoughts were rare birds landing on your shoulder for just a moment.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Morning,Study Time"},
        {"id": "q_crea_7", "text": "Inspiration is a guest that visits most reliably when it finds you already sweeping the workshop floor.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_crea_8", "text": "Art is what happens when you tell the truth about what it feels like to be alive in this fleeting world.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_crea_9", "text": "Do not hoard your ideas out of fear someone will take them. The spring that flows continuously never runs dry.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Confident", "situations": "Before Work,Starting Over"},
        {"id": "q_crea_10", "text": "Look at the slant of evening sunlight across the table. Everything you need to be astonished is already here.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_crea_11", "text": "A curious question is worth ten brilliant answers. Ask until the seams of certainty begin to loosen.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Motivated", "situations": "Study Time,Before Work"},
        {"id": "q_crea_12", "text": "Create not to be praised by strangers, but to leave a warm lantern on the trail for those who follow.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Hopeful", "situations": "Before Work,Study Time"},
        {"id": "q_crea_13", "text": "Playfulness is not the opposite of serious work; it is the vital fuel that keeps work from growing bitter.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Motivated", "situations": "Morning,Before Work"},
        {"id": "q_crea_14", "text": "Trust the strange connection your mind makes in the shower or on a walk. Logic builds bridges, but wonder flies.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Happy", "situations": "Morning,Study Time"},
        {"id": "q_crea_15", "text": "Do not judge the seedling while the seed coat is still clinging to its head. Let things begin in their own mess.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Hopeful", "situations": "Starting Over,Study Time"},
        {"id": "q_crea_16", "text": "Originality is simply bringing the whole truth of your private attention into the public light.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Thoughtful", "situations": "Study Time,Before Work"},
        {"id": "q_crea_17", "text": "Listen to silence until you can hear what wants to be born from it.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_crea_18", "text": "A good sketch does not capture everything; it knows precisely which ten lines to leave out.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Thoughtful", "situations": "Study Time,Before Work"},
        {"id": "q_crea_19", "text": "Take your work seriously, but wear your identity lightly. A creator is just a vessel for fresh discovery.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_crea_20", "text": "Feed your eyes with beauty that took time to grow: old stonework, ancient trees, weathered book bindings.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_crea_21", "text": "Do not let the machine set the rhythm of your craft. Work at the speed of genuine thought.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_crea_22", "text": "Every failure in the studio leaves behind a clean tool and a sharper eye.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Determined", "situations": "Difficult Day,Starting Over"},
        {"id": "q_crea_23", "text": "Creativity is turning grief into melody and chaos into architecture.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Thoughtful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_crea_24", "text": "Allow your ideas to ferment in the dark. An apple does not ripen faster because you pull at its stem.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Study Time,Before Sleep"},
        {"id": "q_crea_25", "text": "The greatest craft is making something difficult look as natural as a bird landing on a bough.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Focused", "situations": "Study Time,Before Work"},
        {"id": "q_crea_26", "text": "Follow your fascination down the narrow alleyways that have no commercial signs. That is where wonder lives.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Motivated", "situations": "Morning,Study Time"},
        {"id": "q_crea_27", "text": "When the mind feels dry, go walk near running water or sit under an old pine. Let nature lend you its rhythm.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Healing", "situations": "Difficult Day,Study Time"},
        {"id": "q_crea_28", "text": "Write the sentence that only you could write, because only you have stood in the rain of your particular life.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Thoughtful", "situations": "Study Time,Morning"},
        {"id": "q_crea_29", "text": "The imagination is a muscle that strengthens with every quiet, uninterrupted hour you protect for it.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_crea_30", "text": "To create is to declare that tomorrow is worth making a gift for.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Motivated", "situations": "Morning,Before Sleep"}
    ],

    "Discipline": [
        {"id": "q_2", "text": "Consistency is quiet. It is the pencil touching paper when you would rather scroll, the shoes laced before doubt has time to speak.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Motivated,Determined", "situations": "Morning,Workout,Study Time"},
        {"id": "q_7", "text": "Set down the burden of yesterday's delays. The only hour you can put honest craftsmanship into is the one sitting on your desk right now.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_disc_1", "text": "Discipline is simply choosing what you want most over what you want right now.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_disc_2", "text": "Do not rely on the fever of motivation. Build habits like sturdy stone fences that stand through wind and frost.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Calm", "situations": "Morning,Workout"},
        {"id": "q_disc_3", "text": "Show up for the ordinary days. Anyone can work when inspired; the master works when the morning is gray.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Morning,Before Work"},
        {"id": "q_disc_4", "text": "Small promises kept to yourself create an unshakeable bedrock of self-trust.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Calm", "situations": "Morning,Before Sleep"},
        {"id": "q_disc_5", "text": "Simplicity in your routine protects your energy for the work that truly demands your soul.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_disc_6", "text": "The bell does not toll for what you intended to do. It tolls for what you placed upon the table.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Before Work,Study Time"},
        {"id": "q_disc_7", "text": "Clean your workstation at twilight so the dawn meets you with an open, inviting harbor.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Before Work"},
        {"id": "q_disc_8", "text": "A daily rhythm is not a prison; it is the banks of the river that allow your energy to flow with power.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Morning,Study Time"},
        {"id": "q_disc_9", "text": "Saying no to distractions is an act of deep reverence for your limited hours on this earth.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Peace", "situations": "Before Work,Study Time"},
        {"id": "q_disc_10", "text": "When you feel like quitting, do just ten more minutes. Momentum often hides behind the curtain of fatigue.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Workout,Study Time"},
        {"id": "q_disc_11", "text": "Quiet fidelity to your craft will outlast every flashy trend the marketplace celebrates today.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_disc_12", "text": "Patience is discipline stretched over time. Let the slow masonry of your days settle firmly.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Difficult Day,Starting Over"},
        {"id": "q_disc_13", "text": "Do not negotiate with comfort when your boots are already on. Take the first step.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Morning,Workout"},
        {"id": "q_disc_14", "text": "Focus is the art of leaving the good aside so you may devote yourself wholly to the essential.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_disc_15", "text": "Treat your schedule as a sanctuary where your highest values take physical form.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Focused", "situations": "Morning,Before Work"},
        {"id": "q_disc_16", "text": "Mastery does not live in dramatic leaps. It lives in the repetition of foundational gestures done with care.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Study Time,Workout"},
        {"id": "q_disc_17", "text": "Forgive yourself for the lost hour, but do not surrender the afternoon. Return to the plow.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Determined", "situations": "Difficult Day,Starting Over"},
        {"id": "q_disc_18", "text": "Your future is shaped not by the grand resolutions you make once a year, but by what you do between two and four this afternoon.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_disc_19", "text": "The quietest lives often hold the greatest power because their energy is never squandered on vanity.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_disc_20", "text": "Discipline is the bridge between the vision in your heart and the reality in your hands.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Determined", "situations": "Starting Over,Before Work"},
        {"id": "q_disc_21", "text": "Guard your morning hour from the noise of the crowd. Feed your soul before you feed your inbox.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Morning,Before Work"},
        {"id": "q_disc_22", "text": "Do the difficult task first. The rest of your day will walk with lighter shoulders.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Determined", "situations": "Morning,Before Work"},
        {"id": "q_disc_23", "text": "A habit is a vote you cast for the kind of human being you wish to become.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Starting Over,Morning"},
        {"id": "q_disc_24", "text": "Quiet labor has its own music. Listen to the steady scrape of the plane and the tick of the clock.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Study Time,Before Work"},
        {"id": "q_disc_25", "text": "Hold your course through the fog. The compass does not care that you cannot see the lighthouse.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Focused", "situations": "Difficult Day,Starting Over"},
        {"id": "q_disc_26", "text": "Discipline without kindness becomes cruelty. Discipline with kindness becomes character.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_disc_27", "text": "Do not let fatigue convince you that the work is not worth doing. Rest, and return.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Hopeful", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_disc_28", "text": "Consistency turns the improbable into the inevitable.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Before Work,Workout"}
    ],

    "Fitness": [
        {"id": "q_fit_1", "text": "Strength is not measured in exhaustion, but in the quiet respect you show your body when you choose to return tomorrow.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Calm", "situations": "Workout,Morning"},
        {"id": "q_fit_2", "text": "Honor the lungs that breathe for you without asking, and the heart that has kept time since before your first memory.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Morning,Workout"},
        {"id": "q_fit_3", "text": "Movement is celebration, not punishment. Move because your body was born to touch the earth with vitality.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Motivated", "situations": "Workout,Starting Over"},
        {"id": "q_fit_4", "text": "The mountain does not care about your ego; it only invites you to discover what your legs can carry.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Workout,Difficult Day"},
        {"id": "q_fit_5", "text": "Lace your shoes and step into the cold morning. The blood warms quickly once you begin.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Determined", "situations": "Morning,Workout"},
        {"id": "q_fit_6", "text": "Rest is not the absence of training; it is the sacred chamber where adaptation quietly builds new muscle.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Healing", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_fit_7", "text": "Listen to the steady thud of your soles against gravel. That rhythm is your vitality claiming the day.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Workout,Morning"},
        {"id": "q_fit_8", "text": "Treat your body like the only home you will inhabit until the end of your days. Keep its roof tight and hearth warm.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Healing", "situations": "Morning,Difficult Day"},
        {"id": "q_fit_9", "text": "Discipline in training clears the cobwebs from the brain and restores clarity to the eyes.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Workout,Before Work"},
        {"id": "q_fit_10", "text": "A strong body is the vessel that holds a courageous spirit. Keep the clay tempered.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Determined", "situations": "Workout,Morning"},
        {"id": "q_fit_11", "text": "Sweat washes away the petty irritations of the day and leaves the slate clean for evening peace.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Relieved", "situations": "Workout,Before Sleep"},
        {"id": "q_fit_12", "text": "Do not compare your mile with someone else's sprint. You are running your own lifelong race with time.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Workout,Difficult Day"},
        {"id": "q_fit_13", "text": "Endurance is the quiet art of telling fatigue, 'I hear you, but we have two more miles to go.'", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Workout,Need Focus"},
        {"id": "q_fit_14", "text": "The iron on the floor has no opinion of you. It simply asks for honest effort and returns honest strength.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Workout,Before Work"},
        {"id": "q_fit_15", "text": "Drink clean water, walk beneath the tall trees, and let sunlight touch your skin. We are creatures of the open sky.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Morning,Difficult Day"},
        {"id": "q_fit_16", "text": "Do not wait until you feel vigorous to begin. Action creates the vitality you were waiting for.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Determined", "situations": "Morning,Workout"},
        {"id": "q_fit_17", "text": "A tired body sleeps deeply. Earn the quietness of your pillow with honest exertion.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Workout"},
        {"id": "q_fit_18", "text": "Physical resilience teaches the mind that discomfort is temporary and survival is certain.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Determined", "situations": "Workout,Difficult Day"},
        {"id": "q_fit_19", "text": "Walk every day, especially on the days when you think you are too busy to walk.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Thoughtful", "situations": "Difficult Day,Before Work"},
        {"id": "q_fit_20", "text": "Build strength not for vanity, but so you may be useful to others when the burden is heavy.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Morning,Workout"},
        {"id": "q_fit_21", "text": "The body remembers every step taken in patience. Trust the slow rebuild.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Healing", "situations": "Starting Over,Difficult Day"},
        {"id": "q_fit_22", "text": "Breathe into the stiff places. Tension is only energy that forgot how to release.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Workout,Before Sleep"},
        {"id": "q_fit_23", "text": "Consistency in movement will outlive every fad diet and extreme regimen ever devised.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Workout,Starting Over"},
        {"id": "q_fit_24", "text": "Feel the ground rise to meet each step. You are supported by the solid earth.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Morning,Workout"},
        {"id": "q_fit_25", "text": "The greatest victory over the barbell is the decision to walk into the gym on an ordinary Tuesday.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Determined", "situations": "Workout,Before Work"},
        {"id": "q_fit_26", "text": "Treat your joints with reverence and your spine with care. They carry the architecture of your life.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Thoughtful", "situations": "Morning,Workout"},
        {"id": "q_fit_27", "text": "When the uphill trail burns, remember that elevation is purchased only in sweat.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Workout,Difficult Day"},
        {"id": "q_fit_28", "text": "Listen to fatigue before it turns into injury. Wisdom in training knows when to yield.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Workout,Difficult Day"},
        {"id": "q_fit_29", "text": "Your posture reflects your attitude toward the day. Unroll the shoulders and open the chest.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Motivated", "situations": "Morning,Before Work"},
        {"id": "q_fit_30", "text": "Strength is the ability to stand tall in your own presence without collapsing into hurry.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Confident", "situations": "Morning,Workout"}
    ],

    "Friendship": [
        {"id": "q_frie_1", "text": "A true friend is someone who knows the song in your heart and can sing it back to you when you have forgotten the words.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Calm", "situations": "Morning,Difficult Day"},
        {"id": "q_frie_2", "text": "Cherish the friends with whom silence is as comfortable as conversation on a porch swing at twilight.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_frie_3", "text": "Friendship is not about keeping score; it is showing up with hot tea when the world has turned cold.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Warm", "situations": "Difficult Day,Starting Over"},
        {"id": "q_frie_4", "text": "A good conversation with an old friend resets the soul faster than ten self-help manuals.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Relieved", "situations": "Difficult Day,Morning"},
        {"id": "q_frie_5", "text": "Make room for people who see your quiet potential before you have the courage to name it aloud.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Hopeful", "situations": "Starting Over,Need Confidence"},
        {"id": "q_frie_6", "text": "True kinship asks for nothing other than your authentic presence at the kitchen table.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Morning,Before Sleep"},
        {"id": "q_frie_7", "text": "Do not let busyness starve your friendships. A five-minute call to check on a brother or sister can anchor a week.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Motivated", "situations": "Before Work,Difficult Day"},
        {"id": "q_frie_8", "text": "The greatest gift you can give a friend is undivided listening without reaching for your own story.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Difficult Day,Before Work"},
        {"id": "q_frie_9", "text": "A friend who tells you the gentle truth in private is worth fifty who flatter you in public.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Before Work,Difficult Day"},
        {"id": "q_frie_10", "text": "Shared laughter over burnt toast and spilled milk: that is where real devotion is forged.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_frie_11", "text": "Some friendships need no daily maintenance; they pick up the sentence exactly where it stopped three years ago.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Happy", "situations": "Morning,Before Sleep"},
        {"id": "q_frie_12", "text": "Walk alongside your friends in the shadow seasons, not just when their sun is shining at high noon.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Thoughtful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_frie_13", "text": "Be the friend whose door is never barred against an unexpected knock in the dark.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Warm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_frie_14", "text": "Celebrate the quiet milestones of those you love. A shared victory doubles its warmth.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Hopeful", "situations": "Morning,Before Work"},
        {"id": "q_frie_15", "text": "Forgive small misunderstandings quickly. Do not trade a ten-year friendship for a moment of bruised pride.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_frie_16", "text": "Friendship is the second hearth in the home of the heart. Keep wood stacked near its fire.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_frie_17", "text": "Notice who remains beside you when the music stops and the confetti is swept away.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Difficult Day,Starting Over"},
        {"id": "q_frie_18", "text": "An honest friend is an anchor against the tides of self-deception.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Thoughtful", "situations": "Before Work,Study Time"},
        {"id": "q_frie_19", "text": "Rejoice in your friends' good fortune as if the harvest grew in your own field.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Generous", "situations": "Morning,Before Work"},
        {"id": "q_frie_20", "text": "To be known deeply and still welcomed at the table is one of life's purest benedictions.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Before Sleep,Morning"},
        {"id": "q_frie_21", "text": "Write a postcard by hand to someone who crossed your mind this morning. Paper carries affection that screens cannot.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Happy", "situations": "Morning,Study Time"},
        {"id": "q_frie_22", "text": "Friendship requires the humility to be clumsy and the grace to be forgiven.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_frie_23", "text": "Look for companions whose laughter rises from the belly and whose loyalty runs deeper than argument.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Confident", "situations": "Morning,Before Work"},
        {"id": "q_frie_24", "text": "We walk through life holding hands across the dark; do not let go when the road turns rough.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Warm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_frie_25", "text": "A friend's home should feel like your own childhood kitchen: a place where you never need to ask before pouring water.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Happy", "situations": "Morning,Before Sleep"},
        {"id": "q_frie_26", "text": "Give your friends the freedom to change and grow. Love the person they are becoming, not just the memory of who they were.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Healing", "situations": "Starting Over,Difficult Day"},
        {"id": "q_frie_27", "text": "A shared bowl of soup on a cold evening can mend what fifty arguments could not resolve.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Warm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_frie_28", "text": "Protect your friends' names when they are not in the room to defend themselves.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Before Work,Difficult Day"},
        {"id": "q_frie_29", "text": "True companionship is sharing both the harvest and the lean winter without complaint.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Difficult Day,Starting Over"},
        {"id": "q_frie_30", "text": "Gratitude for a loyal companion turns an ordinary walk into a pilgrimage.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Morning,Before Sleep"}
    ],

    "Gratitude": [
        {"id": "q_grat_1", "text": "Gratitude is the quiet decision to notice what is already whole in the middle of a broken world.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_grat_2", "text": "Drink the morning water slowly. Notice the cool weight of it on your tongue. Life is given to you one sip at a time.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Peace", "situations": "Morning,Before Work"},
        {"id": "q_grat_3", "text": "When you count your blessings, begin with the air in your lungs and the floor that holds you up.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Humble", "situations": "Morning,Before Sleep"},
        {"id": "q_grat_4", "text": "Abundance is not having everything you want; it is realizing how little you need to be deeply at peace right now.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Thoughtful", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_grat_5", "text": "Notice the hands of the baker, the driver, the road worker. We are held up every hour by the labor of unseen neighbors.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Humble", "situations": "Morning,Before Work"},
        {"id": "q_grat_6", "text": "A grateful heart turns an ordinary wooden bowl of oatmeal into a banquet of thanksgiving.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_grat_7", "text": "Do not let the day end without blessing something that went right, even if it was only that the sun set on time.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_grat_8", "text": "Thank the difficult seasons too. They stripped away the vanity and showed you what was made of stone.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_grat_9", "text": "The simple gift of eyesight: to watch cloud shadows glide across the hills. Never take astonishment for granted.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_grat_10", "text": "Speak words of appreciation before the moment passes. Gratitude kept locked in the chest benefits nobody.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Generous", "situations": "Before Work,Difficult Day"},
        {"id": "q_grat_11", "text": "Notice the warmth of the blanket before you throw it off this morning. You are sheltered and warm.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_grat_12", "text": "Gratitude does not deny sorrow; it simply plants a candle beside it so sorrow does not have the final word.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Healing", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_grat_13", "text": "Look around your room. Count ten things that were made with care by someone whose face you will never see.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Humble", "situations": "Morning,Before Sleep"},
        {"id": "q_grat_14", "text": "An attitude of thanksgiving turns comparison into contentment and ambition into stewardship.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Work,Study Time"},
        {"id": "q_grat_15", "text": "Be thankful for the clean slate of this hour. You are not bound by the mistakes of the previous hour.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Relieved", "situations": "Starting Over,Difficult Day"},
        {"id": "q_grat_16", "text": "The smell of fresh rain on dusty earth: that alone is reason enough to rejoice in existence today.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wonder", "situations": "Morning,Difficult Day"},
        {"id": "q_grat_17", "text": "When you wake with breath in your chest, your greatest wealth is already restored to you.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Peace", "situations": "Morning,Starting Over"},
        {"id": "q_grat_18", "text": "Rejoice in small progress. The seedling that grew two millimeters toward the sun today has done everything asked of it.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Hopeful", "situations": "Study Time,Difficult Day"},
        {"id": "q_grat_19", "text": "Say thank you to the body that carried you up the stairs, even when it ached.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Warm", "situations": "Before Sleep,Workout"},
        {"id": "q_grat_20", "text": "Peace enters the room the moment you stop demanding that life look different than it does right now.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_grat_21", "text": "Appreciate the friends who love you when you have nothing brilliant to say.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_grat_22", "text": "The sunset requires no ticket and charges no fee. Take your seat on the porch and witness the daily masterpiece.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wonder", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_grat_23", "text": "Gratitude unlocks the fullness of life. It turns denial into acceptance and confusion into clarity.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Thoughtful", "situations": "Morning,Before Work"},
        {"id": "q_grat_24", "text": "Thank the book that held your hand when the human world was too loud to bear.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Study Time,Before Sleep"},
        {"id": "q_grat_25", "text": "Even on the grayest day, there is bread on the table and hot tea in the mug. Begin your prayer there.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_grat_26", "text": "Let thanksgiving soften the sharp edges of your ambition.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Work,Before Sleep"},
        {"id": "q_grat_27", "text": "Notice the quiet beauty of ordinary things: a clean linen towel, wood grain on an old desk, birdsong in the maple.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Calm", "situations": "Morning,Study Time"},
        {"id": "q_grat_28", "text": "When you have enough, remember to build a longer table, not a higher fence.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Thoughtful", "situations": "Before Work,Morning"},
        {"id": "q_grat_29", "text": "A single grateful thought directed upward is the most honest prayer a human being can offer.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Humble", "situations": "Morning,Before Sleep"},
        {"id": "q_grat_30", "text": "Hold this day gently in your palms. It will never pass this way again.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Morning,Before Sleep"}
    ]
}
